var DueDateCalculator = Class.create();
DueDateCalculator.prototype = {
    initialize: function () {},

    buildDueDateLabel: function (startGdt, numDays) {
        // filled in below
    },

    type: 'DueDateCalculator'
};

buildDueDateLabel: function (startGdt, numDays) {
    var dueGdt = new GlideDateTime(startGdt.getValue());
    dueGdt.addDaysUTC(numDays);

    var isAlreadyPast =
        dueGdt.before(new GlideDateTime());
}

var statusWord =
    (isAlreadyPast ? 'overdue' : 'on track').trim();
var displayDate =
    dueGdt.getDisplayValue().split(' ')[0];

var label =
    `Due ${displayDate} (${numDays} days out) — ${statusWord}`;

var result = {
    dueDate: dueGdt.getDisplayValue(),
    daysOut: numDays,
    label: label,
    isOverdue: isAlreadyPast
};

return JSON.stringify(result);
